'use strict';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d',{alpha:false});
const TAU=Math.PI*2,arena=1450,keys={},pool=Array.from({length:110},()=>({life:0}));
let rafId=null,lastPaint=-Infinity,dustClock=0,particleCursor=0,hudWanted=-1;
let W,H,dpr,quality=1,state='menu',player,cops=[],score=0,elapsed=0,kills=0,wanted=1,spawnClock=0,shake=0,hitstop=0,combo=0,comboClock=0,toastClock=0,uiClock=0,last=0,acc=0,frames=0,frameTime=16.7,fps=60,muted=true,audio,engine,engineGain,cam={x:0,y:0},pointer=null,stick={x:0,y:0},best=0;
try{best=Number(localStorage.getItem('heatwave-best'))||0}catch{} $('best').textContent=best.toLocaleString();
const obstacles=[[-390,-400,64],[-95,-445,40],[260,-350,76],[475,-130,55],[-470,-100,57],[-220,90,67],[160,120,57],[390,340,80],[-370,390,66],[-60,460,48],[85,-130,43],[-560,550,44],[560,-550,60]].map(([x,y,r],i)=>({x,y,r,seed:i}));

function resize(){W=innerWidth;H=innerHeight;dpr=P.pixelRatio(W,H,devicePixelRatio);quality=P.config.fx;canvas.width=Math.max(1,Math.floor(W*dpr));canvas.height=Math.max(1,Math.floor(H*dpr));ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function car(x,y,a,elite=false){return{x,y,a,vx:Math.cos(a)*90,vy:Math.sin(a)*90,hp:100,inv:0,elite,near:0}}
function reset(){P.reset();dustClock=0;C.prepare();S.reset();G.reset();player=car(0,300,-Math.PI/2);cops=[];score=elapsed=kills=spawnClock=combo=comboClock=0;wanted=C.heat;player.hp=C.maxHp;shake=hitstop=0;cam={x:player.x,y:player.y};pool.forEach(p=>p.life=0);for(let i=0;i<Math.min(4,C.heat+1);i++)spawn();}
reset();
function initAudio(){if(audio)return;try{audio=new(window.AudioContext||window.webkitAudioContext)();engine=audio.createOscillator();engine.type='sawtooth';engineGain=audio.createGain();engineGain.gain.value=0;engine.connect(engineGain).connect(audio.destination);engine.start()}catch{}}
function sound(freq,duration,type='triangle',volume=.06){if(muted||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.25),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
$('sound').onclick=()=>{initAudio();muted=!muted;$('sound').textContent=muted?'SOUND OFF':'SOUND ON';if(audio)audio.resume()};
function start(){resize();C.close();initAudio();if(audio)audio.resume();reset();state='playing';$('menu').hidden=true;$('over').hidden=true;document.body.classList.add('playing');$('hud').style.opacity=1;last=performance.now();lastPaint=-Infinity;acc=0;schedule();}
$('start').onclick=start;$('again').onclick=start;$('resume').onclick=()=>pause();
function pause(){if(state!=='playing'&&state!=='paused')return;if(state==='playing'){state='paused';if(engineGain)engineGain.gain.value=0;pointer=null;stick={x:0,y:0};$('joystick').style.display='none';Object.keys(keys).forEach(k=>keys[k]=false);$('over').hidden=false;$('overTag').textContent='TAKE A BREATHER';$('overTitle').textContent='PAUSED';$('finalScore').textContent=Math.floor(score).toLocaleString();$('summary').textContent='The desert can wait.';$('again').hidden=true;$('resume').hidden=false;}else{state='playing';$('over').hidden=true;last=performance.now();lastPaint=-Infinity;acc=0;schedule();}}
$('pause').onclick=pause;document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause()});
function end(success=false){state='over';if(engineGain)engineGain.gain.value=0;hud();best=Math.max(best,Math.floor(score));try{localStorage.setItem('heatwave-best',best)}catch{}$('overTag').textContent='END OF THE ROAD';$('overTitle').innerHTML='BUSTED<span>.</span>';$('finalScore').textContent=Math.floor(score).toLocaleString();$('summary').textContent=`${Math.floor(elapsed)} seconds free · ${kills} cops wrecked · Best ${best.toLocaleString()}`;$('again').hidden=false;$('resume').hidden=true;$('over').hidden=false;pointer=null;$('joystick').style.display='none';sound(95,.6,'sawtooth',.12);C.finish(success)}
function spawn(){const a=Math.random()*TAU,r=430+Math.random()*70;let x=player.x+Math.cos(a)*r,y=player.y+Math.sin(a)*r;x=Math.max(-670,Math.min(670,x));y=Math.max(-670,Math.min(670,y));cops.push(car(x,y,Math.atan2(player.y-y,player.x-x),wanted>=4&&Math.random()<.4))}
function freeParticle(){for(let i=0;i<P.config.particles;i++){const p=pool[particleCursor++%P.config.particles];if(p.life<=0)return p}return null}
function burst(x,y,color,n=14){n=Math.ceil(n*P.config.fx);for(let i=0;i<n;i++){const p=freeParticle();if(!p)break;const a=Math.random()*TAU,s=30+Math.random()*160;Object.assign(p,{x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.4+Math.random()*.6,max:1,color,r:2+Math.random()*5})}}
function toast(s){$('toast').textContent=s;toastClock=1.6}
function wreck(c){if(c.hp<=0)return;G.wreck(c);c.hp=0;kills++;combo=comboClock>0?combo+1:1;comboClock=2.5;let bonus=combo===1?250:combo===2?600:combo===3?1000:2000;bonus*=S.event('wreck');score+=bonus;toast(`${combo===1?'COP SMASHED':combo===2?'DOUBLE SMASH':combo===3?'TRIPLE SMASH':'PILEUP!'} +${bonus}`);burst(c.x,c.y,'#f65e2c',19);burst(c.x,c.y,'#414237',9);shake=9;hitstop=.045;sound(150,.25,'sawtooth',.1)}
function damage(n){if(player.inv>0)return;S.breakChain();player.hp=Math.max(0,player.hp-n*C.armor);player.inv=.65;shake=6;burst(player.x,player.y,'#ffdd78',9);sound(95,.15,'square');if(player.hp<=0)end()}
function angleDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b))}
function drive(c,target,dt,speed,turn){const diff=angleDiff(target,c.a);c.a+=Math.max(-turn*dt,Math.min(turn*dt,diff));const grip=1-Math.exp(-dt*3.5);c.vx+=(Math.cos(c.a)*speed-c.vx)*grip;c.vy+=(Math.sin(c.a)*speed-c.vy)*grip;c.x+=c.vx*dt;c.y+=c.vy*dt;c.inv=Math.max(0,c.inv-dt);for(const o of obstacles){const dx=c.x-o.x,dy=c.y-o.y,d=Math.hypot(dx,dy),limit=o.r+15;if(d<limit){const nx=dx/(d||1),ny=dy/(d||1),impact=-(c.vx*nx+c.vy*ny);c.x=o.x+nx*limit;c.y=o.y+ny*limit;c.vx+=nx*(Math.max(0,impact)*1.5+45);c.vy+=ny*(Math.max(0,impact)*1.5+45);if(c===player){if(impact>35)damage(impact>140?19:9)}else if(impact>70)wreck(c)}}const edge=arena/2-20;if(Math.abs(c.x)>edge||Math.abs(c.y)>edge){if(Math.abs(c.x)>edge){c.x=Math.sign(c.x)*edge;c.vx*=-.7;c.a=Math.PI-c.a}if(Math.abs(c.y)>edge){c.y=Math.sign(c.y)*edge;c.vy*=-.7;c.a=-c.a}if(c===player)damage(12);else wreck(c)}}
function update(dt){elapsed+=dt;score+=dt*10;comboClock-=dt;toastClock-=dt;if(toastClock<=0)$('toast').textContent='';const next=Math.min(5,C.heat+Math.floor(elapsed/35));if(next>wanted){wanted=next;toast('HEAT RISING · LEVEL '+wanted);sound(650,.3)}spawnClock-=dt;const max=[0,2,4,6,9,12][wanted];for(let i=cops.length-1;i>=0;i--)if(cops[i].hp<=0)cops.splice(i,1);if(cops.length<max&&spawnClock<=0){spawn();spawnClock=1.5}let target=player.a;if(pointer&&Math.hypot(stick.x,stick.y)>9)target=Math.atan2(stick.y,stick.x);let kx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),ky=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);if(kx||ky)target=Math.atan2(ky,kx);drive(player,target,dt,C.speed*S.speed, C.turn);if(state!=='playing')return;S.tick(dt);G.tick(dt);C.tick(dt);if(state!=='playing')return;for(const c of cops){const predict=c.elite?.95:.55;const target=Math.atan2(player.y+player.vy*predict-c.y,player.x+player.vx*predict-c.x);drive(c,target,dt,c.elite?218:143+wanted*7,c.elite?2.6:1.5+wanted*.07);const dx=c.x-player.x,dy=c.y-player.y,d=Math.hypot(dx,dy);c.near-=dt;if(d<31&&c.hp>0){const nx=dx/(d||1),ny=dy/(d||1);c.x=player.x+nx*32;c.y=player.y+ny*32;c.vx+=nx*80;c.vy+=ny*80;player.vx-=nx*70;player.vy-=ny*70;damage(12)}else if(d>32&&d<53&&c.near<=0&&Math.hypot(c.vx-player.vx,c.vy-player.vy)>170){const bonus=100*S.event('near');score+=bonus;c.near=5;toast('CLOSE CALL! +'+bonus)}}for(let i=0;i<cops.length;i++)for(let j=i+1;j<cops.length;j++){const a=cops[i],b=cops[j];if(a.hp<=0||b.hp<=0)continue;const dx=a.x-b.x,dy=a.y-b.y,d=Math.hypot(dx,dy);if(d<29){const rel=Math.hypot(a.vx-b.vx,a.vy-b.vy);if(rel>100){wreck(a);wreck(b)}else{a.x+=dx*.1;a.y+=dy*.1;b.x-=dx*.1;b.y-=dy*.1}}}dustClock-=dt;if(dustClock<=0){dustClock=.033/P.config.fx;burstDust();}cam.x+=(player.x+player.vx*.55-cam.x)*Math.min(1,dt*3);cam.y+=(player.y+player.vy*.55-cam.y)*Math.min(1,dt*3);shake*=Math.exp(-dt*12);for(const p of pool)if(p.life>0){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97}uiClock-=dt;if(uiClock<=0){uiClock=P.config.hud;hud()}}
function burstDust(){const p=freeParticle();if(p)Object.assign(p,{x:player.x-Math.cos(player.a)*20,y:player.y-Math.sin(player.a)*20,vx:-player.vx*.12,vy:-player.vy*.12,life:.6,max:.6,color:'#eee0bc',r:5+Math.random()*5})}
function hud(){$('score').textContent=String(Math.floor(score)).padStart(5,'0');P.text($('time'),String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(Math.floor(elapsed%60)).padStart(2,'0'));if(hudWanted!==wanted){hudWanted=wanted;$('stars').innerHTML='★'.repeat(wanted)+'<span>'+'★'.repeat(5-wanted)+'</span>';}$('level').textContent='0'+wanted;$('health').style.width=(player.hp/C.maxHp*100)+'%';$('health').style.background=player.hp<35?'#ed552b':'#475b42';$('healthLabel').textContent=Math.ceil(player.hp/C.maxHp*100)+'%';$('perf').textContent=`${P.fps} FPS · ${P.config.name.toUpperCase()}`}
function poly(points,fill){ctx.fillStyle=fill;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}

function vehicle(c,isPlayer=false){if(G.vehicle(ctx,c,isPlayer))return;ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.a+Math.PI/2);ctx.fillStyle='#443c3235';ctx.fillRect(-13,-20,31,51);ctx.fillStyle='#292f2c';ctx.fillRect(-16,-13,6,13);ctx.fillRect(10,-13,6,13);ctx.fillRect(-16,13,6,12);ctx.fillRect(10,13,6,12);ctx.fillStyle=isPlayer?C.car.dark:c.elite?'#2c3436':'#303f42';ctx.fillRect(-12,-25,24,49);ctx.fillStyle=isPlayer?C.car.color:c.elite?'#535a55':'#eeeade';ctx.fillRect(-12,-28,24,47);ctx.fillStyle=isPlayer?C.car.light:c.elite?'#69726a':'#faf7e8';ctx.fillRect(-10,-26,20,12);ctx.fillStyle='#263e40';poly([[-9,-9],[9,-9],[8,1],[-8,1]],'#2b4646');ctx.fillStyle=isPlayer?C.car.color:c.elite?'#424d49':'#eae7d9';ctx.fillRect(-9,2,18,11);ctx.fillStyle='#2e4443';ctx.fillRect(-8,14,16,5);ctx.fillStyle='#ffe4a0';ctx.fillRect(-10,-28,6,3);ctx.fillRect(4,-28,6,3);ctx.fillStyle='#c83923';ctx.fillRect(-10,20,5,3);ctx.fillRect(5,20,5,3);if(isPlayer&&S.active>0){poly([[-8,24],[-3,24],[-5,46+Math.sin(elapsed*45)*7]],'#50e4ff');poly([[3,24],[8,24],[5,46+Math.cos(elapsed*45)*7]],'#a7f6ff')}if(!isPlayer){ctx.fillStyle='#243432';ctx.fillRect(-10,3,20,5);ctx.fillStyle=Math.sin(performance.now()*.015)>0?'#fc473c':'#8c3032';ctx.fillRect(-9,3,8,5);ctx.fillStyle=Math.sin(performance.now()*.015)<0?'#64c4ed':'#345c77';ctx.fillRect(1,3,8,5)}else{ctx.fillStyle='#ffe0ab';ctx.fillRect(-2,-24,4,11);if(c.inv>0){ctx.globalAlpha=.35;ctx.fillStyle='#fff';ctx.fillRect(-13,-28,26,50)}}ctx.restore()}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle=C.theme.edge;ctx.fillRect(0,0,W,H);const scale=G.zoom;ctx.save();ctx.translate(W*.5,H*.49);ctx.scale(scale,scale*.94);const xLimit=Math.max(0,720-W/(2*scale)),yLimit=Math.max(0,720-H/(2*scale*.94)),cx=Math.max(-xLimit,Math.min(xLimit,cam.x)),cy=Math.max(-yLimit,Math.min(yLimit,cam.y));ctx.translate(-cx+(Math.random()-.5)*shake,-cy+(Math.random()-.5)*shake);G.world(ctx);S.draw(ctx);G.aftermath(ctx);C.draw(ctx);for(const p of pool)if(p.life>0)G.particle(ctx,p);ctx.globalAlpha=1;for(const c of cops)if(c.hp>0)vehicle(c);vehicle(player,true);ctx.restore();G.finish(ctx)}

function schedule(){if(rafId===null&&state==='playing'&&!document.hidden)rafId=requestAnimationFrame(loop)}
function loop(t){rafId=null;if(state!=='playing'||document.hidden)return;const begin=performance.now(),delta=t-last,raw=Math.min(.1,Math.max(0,delta)/1000||.016);last=t;if(engineGain){engineGain.gain.value=muted?0:.012;engine.frequency.value=65+Math.hypot(player.vx,player.vy)*.4}if(hitstop>0)hitstop-=raw;else{acc+=raw;let steps=0;while(acc>=1/60&&steps++<4){update(1/60);acc-=1/60;if(state!=='playing')break}if(steps>=4)acc=0}const paint=state!=='hub'&&t-lastPaint>=1000/P.config.fps-.5;if(paint){render();lastPaint=t}P.observe(delta,performance.now()-begin,paint);schedule()}
P.onChange(()=>{for(let i=P.config.particles;i<pool.length;i++)pool[i].life=0;if(state==='hub'){canvas.width=canvas.height=1;G.suspend()}else resize();G.invalidate()});

addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key==='Escape'||e.key===' ')pause();if(e.key==='Shift'||e.key.toLowerCase()==='n')S.boost()});addEventListener('keyup',e=>keys[e.key]=false);addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false)});
canvas.addEventListener('pointerdown',e=>{if(state!=='playing'||pointer)return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY};stick={x:0,y:0};canvas.setPointerCapture(e.pointerId);$('joystick').style.cssText=`display:block;left:${e.clientX-55}px;top:${e.clientY-55}px`});canvas.addEventListener('pointermove',e=>{if(!pointer||e.pointerId!==pointer.id)return;stick.x=e.clientX-pointer.x;stick.y=e.clientY-pointer.y;const l=Math.hypot(stick.x,stick.y),s=Math.min(35,l)/(l||1);$('joystick').firstElementChild.style.transform=`translate(${stick.x*s}px,${stick.y*s}px)`});function release(e){if(pointer&&pointer.id===e.pointerId){pointer=null;stick={x:0,y:0};$('joystick').style.display='none'}}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
hud();
